409	    @Test
410	    void concurrentApprovesNeverExceedAvailableTotal() throws Exception {
411	        long windowId = createWindow("ch-conc-" + run,
412	                "2026-10-14T00:00:00Z", "2026-10-14T02:00:00Z", "1.000");
413	        List<String> allocationKeys = new ArrayList<>();
414	        for (int i = 0; i < 10; i++) {
415	            allocationKeys.add(submitAllocation(windowId, "user-" + i, "0.2", "alice"));
416	        }
417	        ExecutorService pool = Executors.newFixedThreadPool(10);
418	        CountDownLatch gate = new CountDownLatch(1);
419	        List<Future<Integer>> futures = new ArrayList<>();
420	        for (String allocationKey : allocationKeys) {
421	            String commandKey = key("ap");
422	            futures.add(pool.submit(() -> {
423	                gate.await();
424	                try {
425	                    waterService.approveAllocation(commandKey, allocationKey);
426	                    return 200;
427	                } catch (ApiException e) {
428	                    return e.status().value();
429	                }
430	            }));
431	        }
432	        gate.countDown();
433	        int ok = 0;
434	        int quota = 0;
435	        for (Future<Integer> future : futures) {
436	            int status = future.get(30, TimeUnit.SECONDS);
437	            if (status == 200) {
438	                ok++;
439	            } else if (status == 422) {
440	                quota++;
441	            }
442	        }
443	        pool.shutdown();
444	        assertEquals(5, ok, "恰好 5 个 0.2 可以放入 1.000");
445	        assertEquals(5, quota);
446	        JsonNode cap = capacity(windowId);
447	        assertEquals("1", cap.get("approvedTotal").asText());
