483	        int curtailStatus = curtailFuture.get(30, TimeUnit.SECONDS);
484	        pool.shutdown();
485	
486	        // 按事务提交顺序：恰好一个成功（先批准 6+4=10 则限供 8 冲突；先限供 8 则批准 10 超额）
487	        assertTrue((approveStatus == 200) != (curtailStatus == 200),
